var lossHinge = require( './fixtures/python/loss-functions/loss_hinge.json' );
var lossSquaredHinge = require( './fixtures/python/loss-functions/loss_squared_hinge.json' );
var lossPerceptron = require( './fixtures/python/loss-functions/loss_perceptron.json' );
var lossModifiedHuber = require( './fixtures/python/loss-functions/loss_modified_huber.json' );
var lossLog = require( './fixtures/python/loss-functions/loss_log.json' );
