var manyEpochs = require( './fixtures/python/many_epochs.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dsgdTrainer, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 12', function test( t ) {
	t.strictEqual( dsgdTrainer.length, 12, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var params;
	var data;
	var i;

	data = penaltyL2;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	params = new Float64Params({
		'penalty': penalty2enum( data.penalty ),
		'learningRate': lr2enum( data.learning_rate ),
		'lossFunction': loss2enum( data.loss_function ),
		'penaltyParams': new Float64Array( [ data.lambda, data.l1_ratio ] ),
		'learningRateParams': new Float64Array( [ data.eta0, data.power_t ] ),
		'lossFunctionParams': new Float64Array( [ data.epsilon ] ),
		'intercept': data.intercept,
		'maxIter': data.max_iter,
		'fitIntercept': data.fit_intercept
	});

	params = new Float64Params(params );

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dsgdTrainer( value, data.M, data.N, new Float64Array( data.X ), data.LDX, new Float64Array( data.y ), 1, new Float64Array( data.N+1 ), 1, new Float64Array( data.N ), 1, params );
		};
	}
});

