tape( 'the function trains a linear model via stochastic gradient descent (no penalty)', function test( t ) {
	var workspace;
	var params;
	var data;
	var out;
	var w;
	var i;

	data = penaltyNone;

	w = new Float64Array( data.w );
	workspace = new Float64Array( data.workspace );

	params = new Float64Params({
		'penalty': penalty2enum( data.penalty ),
		'learningRate': lr2enum( data.learning_rate ),
		'lossFunction': loss2enum( data.loss_function ),
		'penaltyParams': new Float64Array( [ data.lambda, data.l1_ratio ] ),
		'learningRateParams': new Float64Array( [ data.eta0, data.power_t ] ),
		'lossFunctionParams': new Float64Array( [ data.epsilon ] ),
		'intercept': data.intercept,
		'maxIter': data.max_iter,
		'fitIntercept': data.fit_intercept
	});

	out = dsgdTrainer( data.order, data.M, data.N, new Float64Array( data.X ), data.LDX, new Float64Array( data.y ), 1, w, 1, workspace, 1, params );

	t.strictEqual( out, w, 'returns expected value' );
	for ( i = 0; i < data.N; i++ ) {
		t.strictEqual( isAlmostSameValue( out[ i ], data.expected_w[ i ], 0 ), true, 'returns expected coefficient '+i );
	}
	t.strictEqual( isAlmostSameValue( out[ data.N ], data.expected_intercept, 0 ), true, 'returns expected intercept' );

	t.end();
});

